window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dcf9854bbb76951e"]={"versions": [{"id": "FIG-dcf9854bbb76951e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell- / Konfigurationsausschnitt, Paketrahmen <code>HM_HealthChannel</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R20-11), Spezifikation <em>Platform Health Management</em> (PHM).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Metamodell-Struktur für die <strong>Health-Channel-Supervision</strong>. Im Gegensatz zu kontrollflussbasierten Mechanismen (Alive-, Deadline- und Logical-Supervision über Checkpoints) dient der Health Channel der statischen und zustandsbasierten Überwachung diskreter System-, Hardware- oder Applikationszustände (z. B. Sensorausfall, Speicherfehler, interne Degradation).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>HealthChannel</code> (Klasse):</strong></li>\n<li>Repräsentiert einen logischen Überwachungskanal innerhalb des PHM.</li>\n<li><em>Attribute:</em></li>\n<li><code>Name</code>: Eindeutiger Bezeichner des Überwachungskanals.</li>\n<li><code>ID</code>: Numerische Kennung zur internen Adressierung und Laufzeit-Identifikation bei IPC-/API-Aufrufen.</li>\n<li><code>HealthStatusInitValue</code>: Initialer Gesundheitszustand, der dem Kanal beim Systemstart bzw. vor dem Eintreffen der ersten Statusmeldung zugewiesen wird.</li>\n<li><strong><code>HealthStatus</code> (Klasse):</strong></li>\n<li>Repräsentiert einen diskreten, gültigen Zustandswert, den der zugehörige Kanal annehmen kann (z. B. <code>OK</code>, <code>DEGRADED</code>, <code>FATAL_ERROR</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>Name</code>: Symbolischer Bezeichner des Zustands.</li>\n<li><code>ID</code>: Numerischer Enumerate-Wert, der über die Laufzeitschnittstelle übertragen wird.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Komposition (<code>HealthChannel</code> $\\blacklozenge$--- <code>HealthStatus</code>):</strong> Ein <code>HealthChannel</code> besitzt die vollständige Existenzabhängigkeit (Lebenszyklus-Hoheit) über seine zugeordneten <code>HealthStatus</code>-Instanzen. Ein Zustandswert existiert nur im Kontext seines Kanals ($1$ zu $1..\\ast$).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Beim Hochfahren der Adaptive Application und des PHM-Daemons befindet sich der Kanal im Zustand <code>HealthStatusInitValue</code>.</li>\n<li><strong>Laufzeit-Trigger (Meldung):</strong> Eine überwachte Entität (Applikation, Treiber oder HW-Monitor) meldet ihren Status via IPC/API (<code>ReportHealthStatus(HealthChannelId, HealthStatusId)</code>) synchron an die lokale PHM-Laufzeitbibliothek.</li>\n<li><strong>Validierung & Zustandsübergang:</strong> Der PHM-Daemon prüft, ob die gemeldete <code>HealthStatusId</code> Teil der für den Kanal konfigurierten <code>HealthStatus</code>-Menge ist. Bei Übereinstimmung wechselt der Kanalzustand.</li>\n<li><strong>Auswertung & Recovery:</strong> Der aktuelle Zustand speist die PHM-Regel-Engine (<em>Supervision Condition</em> / <em>Logical Expression</em>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verlässt der Kanal den Normalzustand oder nimmt einen definierten Fehlerstatus ein, wird die zugeordnete <em>Recovery Action</em> getriggert (z. B. Prozessneustart über <em>Execution Management</em>, Transition über <em>State Management</em> oder Fehlereintrag via <em>Diagnostic Management</em>).</li>\n<li>Bei Meldung unkonfigurierter IDs greift die Fehlerbehandlung des PHM (z. B. Reporting an die Logging/Security-Infrastruktur).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsvertrag (ARXML):</strong></li>\n<li>Für jeden Kanal müssen alle erwarteten Statuswerte inklusive Initialzustand (<code>HealthStatusInitValue</code>) lückenlos im Manifest modelliert werden. Nicht deklarierte IDs zur Laufzeit führen zu API-Fehlern (<code>ara::phm</code>-Fehlercodes) und verwerfen die Meldung.</li>\n<li><strong>API & Applikations-Entwicklung (<code>ara::phm</code>):</strong></li>\n<li>Applikationen instanziieren ein kanalbezogenes Interface-Objekt (z. B. <code>ara::phm::HealthChannel</code>).</li>\n<li>Die Aufrufe sollten zustandsändernd oder bei Erreichen kritischer Degradationsstufen erfolgen; sie erfordern deterministische Zuordnung der im Manifest definierten numerischen IDs zu lokalen Enums.</li>\n<li><strong>Stack- & Plattform-Integration:</strong></li>\n<li>Der PHM-Daemon muss threadsicher und nicht-blockierend ausgelegt sein, um Meldungen mehrerer Channels aus verschiedenen Prozessen/Kernen ohne Priority-Inversion zu konsolidieren.</li>\n</ul>"}, {"id": "FIG-47c0deeb1a16caa4", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell- / Konfigurationsausschnitt, Paketrahmen <code>HM_HealthChannel</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R20-11), Spezifikation <em>Platform Health Management</em> (PHM).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Metamodell-Struktur für die <strong>Health-Channel-Supervision</strong>. Im Gegensatz zu kontrollflussbasierten Mechanismen (Alive-, Deadline- und Logical-Supervision über Checkpoints) dient der Health Channel der statischen und zustandsbasierten Überwachung diskreter System-, Hardware- oder Applikationszustände (z. B. Sensorausfall, Speicherfehler, interne Degradation).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>HealthChannel</code> (Klasse):</strong></li>\n<li>Repräsentiert einen logischen Überwachungskanal innerhalb des PHM.</li>\n<li><em>Attribute:</em></li>\n<li><code>Name</code>: Eindeutiger Bezeichner des Überwachungskanals.</li>\n<li><code>ID</code>: Numerische Kennung zur internen Adressierung und Laufzeit-Identifikation bei IPC-/API-Aufrufen.</li>\n<li><code>HealthStatusInitValue</code>: Initialer Gesundheitszustand, der dem Kanal beim Systemstart bzw. vor dem Eintreffen der ersten Statusmeldung zugewiesen wird.</li>\n<li><strong><code>HealthStatus</code> (Klasse):</strong></li>\n<li>Repräsentiert einen diskreten, gültigen Zustandswert, den der zugehörige Kanal annehmen kann (z. B. <code>OK</code>, <code>DEGRADED</code>, <code>FATAL_ERROR</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>Name</code>: Symbolischer Bezeichner des Zustands.</li>\n<li><code>ID</code>: Numerischer Enumerate-Wert, der über die Laufzeitschnittstelle übertragen wird.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Komposition (<code>HealthChannel</code> $\\blacklozenge$--- <code>HealthStatus</code>):</strong> Ein <code>HealthChannel</code> besitzt die vollständige Existenzabhängigkeit (Lebenszyklus-Hoheit) über seine zugeordneten <code>HealthStatus</code>-Instanzen. Ein Zustandswert existiert nur im Kontext seines Kanals ($1$ zu $1..\\ast$).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Beim Hochfahren der Adaptive Application und des PHM-Daemons befindet sich der Kanal im Zustand <code>HealthStatusInitValue</code>.</li>\n<li><strong>Laufzeit-Trigger (Meldung):</strong> Eine überwachte Entität (Applikation, Treiber oder HW-Monitor) meldet ihren Status via IPC/API (<code>ReportHealthStatus(HealthChannelId, HealthStatusId)</code>) synchron an die lokale PHM-Laufzeitbibliothek.</li>\n<li><strong>Validierung & Zustandsübergang:</strong> Der PHM-Daemon prüft, ob die gemeldete <code>HealthStatusId</code> Teil der für den Kanal konfigurierten <code>HealthStatus</code>-Menge ist. Bei Übereinstimmung wechselt der Kanalzustand.</li>\n<li><strong>Auswertung & Recovery:</strong> Der aktuelle Zustand speist die PHM-Regel-Engine (<em>Supervision Condition</em> / <em>Logical Expression</em>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verlässt der Kanal den Normalzustand oder nimmt einen definierten Fehlerstatus ein, wird die zugeordnete <em>Recovery Action</em> getriggert (z. B. Prozessneustart über <em>Execution Management</em>, Transition über <em>State Management</em> oder Fehlereintrag via <em>Diagnostic Management</em>).</li>\n<li>Bei Meldung unkonfigurierter IDs greift die Fehlerbehandlung des PHM (z. B. Reporting an die Logging/Security-Infrastruktur).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsvertrag (ARXML):</strong></li>\n<li>Für jeden Kanal müssen alle erwarteten Statuswerte inklusive Initialzustand (<code>HealthStatusInitValue</code>) lückenlos im Manifest modelliert werden. Nicht deklarierte IDs zur Laufzeit führen zu API-Fehlern (<code>ara::phm</code>-Fehlercodes) und verwerfen die Meldung.</li>\n<li><strong>API & Applikations-Entwicklung (<code>ara::phm</code>):</strong></li>\n<li>Applikationen instanziieren ein kanalbezogenes Interface-Objekt (z. B. <code>ara::phm::HealthChannel</code>).</li>\n<li>Die Aufrufe sollten zustandsändernd oder bei Erreichen kritischer Degradationsstufen erfolgen; sie erfordern deterministische Zuordnung der im Manifest definierten numerischen IDs zu lokalen Enums.</li>\n<li><strong>Stack- & Plattform-Integration:</strong></li>\n<li>Der PHM-Daemon muss threadsicher und nicht-blockierend ausgelegt sein, um Meldungen mehrerer Channels aus verschiedenen Prozessen/Kernen ohne Priority-Inversion zu konsolidieren.</li>\n</ul>"}], "trans": [{"from": "FIG-dcf9854bbb76951e", "to": "FIG-47c0deeb1a16caa4", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
